a) $4\sqrt{x}-2 = 2 \quad $ với $x \ge 0 \quad$        b) $4\sqrt{x-3}-2 = 2 \quad $ với $ x \ge 3$ 

c) $3(x-3)^{2}-2=4 \quad\quad$               d) $\sqrt{\left(3x-3\right)^{2}} = 1$

e) $\dfrac{4}{3}-2\sqrt{x+4} = 1$
\loigiai{
a) $x=1 \quad\quad$ b) $x=4 \quad\quad$  c) $x=3+\sqrt{2}\quad$ và $x=3-\sqrt{2}$\\
d) $x=\dfrac{4}{3}\quad$ , $x=\dfrac{2}{3}\quad\quad$      e) $x=- \dfrac{143}{36}$
}\end{ex}

\begin{ex}%[7D2V1]
Tìm ${x}$ 

a) $\sqrt{x}-\dfrac{1}{3} = \dfrac{3}{4} \quad $ với $x \ge 0 \quad$        b) $\sqrt{x-4}-\dfrac{1}{3} = \dfrac{3}{4} \quad $ với $ x \ge 4$ 

c) $4(x-1)^{2}-4=2 \quad\quad$               d) $\sqrt{\left(x-4\right)^{2}} = 1$

e) $\dfrac{4}{3}-\dfrac{1}{3}\sqrt{x+2} = \dfrac{1}{2}$
\loigiai{
a) $x=\dfrac{169}{144} \quad\quad$ b) $x=\dfrac{745}{144} \quad\quad$  c) $x=4+\sqrt{\dfrac{3}{2}}\quad$ và $x=4-\sqrt{\dfrac{3}{2}}$\\
d) $x=5\quad$ , $x=3\quad\quad$      e) $x=\dfrac{17}{4}$
}\end{ex}

\begin{ex}%[7D2V1]
Tìm ${x}$ 

a) $\dfrac{1}{2}\sqrt{x}-\dfrac{2}{3} = 2 \quad $ với $x \ge 0 \quad$        b) $\dfrac{1}{2}\sqrt{x-4}-\dfrac{2}{3} = 2 \quad $ với $ x \ge 4$ 

c) $4(x-3)^{2}-2=1 \quad\quad$               d) $\sqrt{\left(3x-4\right)^{2}} = \dfrac{1}{4}$

e) $\dfrac{2}{3}-\dfrac{2}{3}\sqrt{x+1} = 2$
\loigiai{
a) $x=\dfrac{256}{9} \quad\quad$ b) $x=\dfrac{292}{9} \quad\quad$  c) $x=4+\sqrt{\dfrac{3}{4}}\quad$ và $x=4-\sqrt{\dfrac{3}{4}}$\\
d) $x=\dfrac{17}{12}\quad$ , $x=\dfrac{5}{4}\quad\quad$      e) $x=3$
}\end{ex}
